document.addEventListener('DOMContentLoaded',()=>{
 const script=[...document.scripts].find(s=>s.src.includes('notebook.js'));const base=new URL('../',script.src);
 const sidebar=document.querySelector('.sidebar-search-container');if(sidebar){const a=document.createElement('a');a.className='quick-search';a.href=new URL('tags.html',base);a.textContent='⌕ 全文检索与标签  /';sidebar.after(a);const form=sidebar.querySelector('form');if(form)form.addEventListener('submit',e=>{e.preventDefault();location.href=new URL('tags.html?q='+encodeURIComponent(form.querySelector('input[name=q]').value),base)})}
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();location.href=new URL('tags.html',base)}});
 document.querySelectorAll('.highlight').forEach(el=>{const b=document.createElement('button');b.className='copy-code';b.textContent='复制';b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(el.querySelector('pre').innerText);b.textContent='已复制';setTimeout(()=>b.textContent='复制',1500)}catch{b.textContent='请选中文本复制'}});el.append(b)});
 const q=document.querySelector('#filter-query');if(q){const catalog=window.NOTEBOOK_CATALOG||[];let tag='全部';const box=document.querySelector('#tag-buttons');const out=document.querySelector('#filter-results');q.value=new URLSearchParams(location.search).get('q')||'';function render(){out.replaceChildren();let hits=catalog.filter(r=>(tag==='全部'||r.tags.includes(tag))&&[r.title,r.body,r.tags.join(' ')].join(' ').toLowerCase().includes(q.value.trim().toLowerCase()));const count=document.createElement('p');count.className='muted';count.textContent=hits.length?`找到 ${hits.length} 篇内容`:'暂无结果，请尝试其他关键词或标签。';out.append(count);hits.forEach(r=>{const div=document.createElement('div');div.className='result';const a=document.createElement('a');a.href=new URL(r.path,base);a.textContent=r.title;const p=document.createElement('p');p.textContent=r.summary||'查看内容与相关记录';const small=document.createElement('small');small.textContent=r.tags.join(' · ');div.append(a,p,small);out.append(div)})}['全部',...new Set(catalog.flatMap(r=>r.tags))].forEach(t=>{const b=document.createElement('button');b.textContent=t;b.classList.toggle('active',t===tag);b.onclick=()=>{tag=t;box.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()};box.append(b)});q.oninput=render;render()}
 const tracker=document.querySelector('.tracker');if(tracker){const checks=[...tracker.querySelectorAll('input')];const key='robotics-notebook:'+tracker.dataset.project;try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved)&&saved.length===checks.length)checks.forEach((x,i)=>x.checked=!!saved[i])}catch{}function update(save){let n=checks.filter(x=>x.checked).length;document.querySelector('#progress-label').textContent=`${n*20}% · ${n} / 5 已完成`;document.querySelector('#progress').value=n;if(save)try{localStorage.setItem(key,JSON.stringify(checks.map(x=>x.checked)))}catch{tracker.querySelector('.muted').textContent='浏览器存储不可用，请导出进度以保存。'}}checks.forEach(x=>x.onchange=()=>update(true));update(false);document.querySelector('#export-progress').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({project:tracker.dataset.project,updated:new Date().toISOString(),milestones:checks.map(x=>({title:x.parentElement.textContent.trim(),done:x.checked}))},null,2)],{type:'application/json'}));a.download='mobile-robot-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
});
